        // Offloads Reload() to the thread pool. Safe to call from request/AMQP threads.
        public static async Task ReloadAsync(CancellationToken cancellationToken = default)
        {
            await ReloadGate.WaitAsync(cancellationToken).ConfigureAwait(false);
            try
            {
                await Task.Run(() => Reload(), cancellationToken).ConfigureAwait(false);
            }
            finally
            {
                ReloadGate.Release();
            }
